package cz.mh.rallye.rallye_backend.competition.domain;
import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;
import static cz.mh.rallye.rallye_backend.competition.domain.RaceEvaluator.RuleViolation;
/** Bounded, offline parser. URLs are data and are never dereferenced. */
public final class GpsParser {
 private GpsParser(){}
 public record Coordinates(double latitude,double longitude,String format,String canonical){}
 private record Component(double value,int count){}
 public static Coordinates parse(String input){if(input==null||input.isBlank()||input.getBytes(StandardCharsets.UTF_8).length>2048)throw new RuleViolation("INVALID_COORDINATES");String text=input.strip();if(text.matches("(?i)^https?://.*"))return url(text);return pair(text);}
 private static Coordinates result(double lat,double lon,String format){GpsMath.validate(lat,lon);return new Coordinates(lat,lon,format,String.format(Locale.ROOT,"%.6f, %.6f",lat,lon));}
 private static Coordinates pair(String raw){String s=raw.toUpperCase(Locale.ROOT).replace(' ',' ').strip();Matcher prefix=Pattern.compile("^([NSEW])\\s*(.*?)\\s*[,;]?\\s*([NSEW])\\s*(.*?)$").matcher(s);Matcher suffix=Pattern.compile("^(.*?)\\s*([NSEW])\\s*[,;]?\\s*(.*?)\\s*([NSEW])$").matcher(s);String left,right;Character h1=null,h2=null;
  if(prefix.matches()){h1=prefix.group(1).charAt(0);left=prefix.group(2);h2=prefix.group(3).charAt(0);right=prefix.group(4);}else if(suffix.matches()){left=suffix.group(1);h1=suffix.group(2).charAt(0);right=suffix.group(3);h2=suffix.group(4).charAt(0);}else{if(s.matches(".*[NSEW].*"))throw new RuleViolation("INVALID_COORDINATES");String[] parts;if(s.contains(";"))parts=s.split(";",-1);else if(s.chars().filter(c->c==',').count()==1)parts=s.split(",",-1);else if(s.indexOf(',')>=0)throw new RuleViolation("AMBIGUOUS_COORDINATES");else parts=s.split("\\s+");if(parts.length!=2)throw new RuleViolation("AMBIGUOUS_COORDINATES");left=parts[0];right=parts[1];}
  if(h1!=null&&(("NS".indexOf(h1)>=0)==("NS".indexOf(h2)>=0)))throw new RuleViolation("INVALID_COORDINATES");
  var a=component(left,h1);var b=component(right,h2);if(a.count()!=b.count())throw new RuleViolation("AMBIGUOUS_COORDINATES");boolean swapped=h1!=null&&"EW".indexOf(h1)>=0;return result(swapped?b.value():a.value(),swapped?a.value():b.value(),a.count()==1?"DD":a.count()==2?"DMM":"DMS");
 }
 private static Component component(String raw,Character hemisphere){String s=raw.replace('°',' ').replace('′',' ').replace('’',' ').replace((char)39,' ').replace('″',' ').replace((char)34,' ').strip().replace(',','.');String[] nums=s.split("\\s+");if(nums.length<1||nums.length>3)throw new RuleViolation("INVALID_COORDINATES");double[] values=new double[nums.length];for(int i=0;i<nums.length;i++){if(!nums[i].matches(i==0?"[+-]?[0-9]+(?:\\.[0-9]+)?":"[0-9]+(?:\\.[0-9]+)?"))throw new RuleViolation("INVALID_COORDINATES");try{values[i]=Double.parseDouble(nums[i]);}catch(NumberFormatException e){throw new RuleViolation("INVALID_COORDINATES");}if(!Double.isFinite(values[i]))throw new RuleViolation("INVALID_COORDINATES");}
  if(nums.length>1&&(values[0]!=Math.rint(values[0])||values[1]>=60))throw new RuleViolation("INVALID_COORDINATES");if(nums.length==3&&(values[1]!=Math.rint(values[1])||values[2]>=60))throw new RuleViolation("INVALID_COORDINATES");double magnitude=Math.abs(values[0])+(nums.length>1?values[1]/60:0)+(nums.length>2?values[2]/3600:0);boolean negative=nums[0].startsWith("-");if(hemisphere!=null){boolean southWest="SW".indexOf(hemisphere)>=0;if(negative&&!southWest||nums[0].startsWith("+")&&southWest)throw new RuleViolation("COORDINATE_SIGN_CONFLICT");negative=southWest;}
  return new Component(negative?-magnitude:magnitude,nums.length);
 }
 private static Coordinates url(String text){try{URI uri=URI.create(text);String host=uri.getHost();if(host==null||uri.getUserInfo()!=null||uri.getPort()!=-1||!Set.of("www.google.com","google.com","maps.apple.com","www.openstreetmap.org","openstreetmap.org","mapy.cz","mapy.com").contains(host.toLowerCase(Locale.ROOT)))throw new RuleViolation("MAP_URL_UNSUPPORTED");Map<String,String> query=new HashMap<>();if(uri.getRawQuery()!=null)for(String pair:uri.getRawQuery().split("&")){String[] kv=pair.split("=",2);String key=URLDecoder.decode(kv[0],StandardCharsets.UTF_8),value=kv.length==2?URLDecoder.decode(kv[1],StandardCharsets.UTF_8):"";if(query.putIfAbsent(key,value)!=null)throw new RuleViolation("AMBIGUOUS_COORDINATES");}
  int families=(query.containsKey("q")?1:0)+(query.containsKey("ll")?1:0)+(query.containsKey("x")||query.containsKey("y")?1:0);if(families>1)throw new RuleViolation("AMBIGUOUS_COORDINATES");String value=null;host=host.toLowerCase(Locale.ROOT);String path=uri.getPath();
  if(Set.of("www.google.com","google.com").contains(host)&&path.startsWith("/maps")){Matcher m=Pattern.compile("^/maps/@([+-]?[0-9.]+),([+-]?[0-9.]+),[^/]+$").matcher(path);if(m.matches())value=m.group(1)+","+m.group(2);if(query.containsKey("q")){if(value!=null)throw new RuleViolation("AMBIGUOUS_COORDINATES");value=query.get("q");}}
  else if(host.equals("maps.apple.com")&&path.equals("/"))value=query.get("ll");
  else if(host.endsWith("openstreetmap.org")&&path.equals("/")&&uri.getFragment()!=null){Matcher m=Pattern.compile("map=[0-9]+/([+-]?[0-9.]+)/([+-]?[0-9.]+)").matcher(uri.getFragment());if(m.matches())value=m.group(1)+","+m.group(2);}
  else if((host.equals("mapy.cz")&&path.equals("/zakladni")||host.equals("mapy.com")&&path.equals("/cs/zakladni"))&&query.containsKey("x")&&query.containsKey("y"))value=query.get("y")+","+query.get("x");
  if(value==null||!value.matches("[+-]?[0-9]+(?:\\.[0-9]+)?,\\s*[+-]?[0-9]+(?:\\.[0-9]+)?"))throw new RuleViolation("MAP_URL_UNSUPPORTED");String[] pair=value.split(",");return result(Double.parseDouble(pair[0].strip()),Double.parseDouble(pair[1].strip()),"MAP_URL");
 }catch(RuleViolation e){throw e;}catch(RuntimeException e){throw new RuleViolation("MAP_URL_UNSUPPORTED");}}
}
